$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'ESLettaAdapter.psm1') -Force
$cases=[Collections.Generic.List[object]]::new();function C($n,$b){[void]$cases.Add([pscustomobject]@{case=$n;status=$(if($b){'passed'}else{'failed'})})}
$m=New-ESLettaMemory -BlockId 'task-focus' -Value 'initial';try{Update-ESLettaMemory -Block $m -Value 'x' -ExpectedVersion 1;C 'confirmation-required' $false}catch{C 'confirmation-required' $true};$m=Update-ESLettaMemory -Block $m -Value 'confirmed-focus' -ExpectedVersion 1 -UserConfirmed;C 'version-update' ($m.version -eq 2);$p=New-ESLettaContextProjection -Block $m;C 'projection-replay' ((Test-ESLettaProjectionReplay -Projection $p).status -eq 'passed');try{Update-ESLettaMemory -Block $m -Value 'stale' -ExpectedVersion 1 -UserConfirmed;C 'stale-rejected' $false}catch{C 'stale-rejected' $true};try{New-ESLettaMemory -BlockId 'too-big' -Value ('x'*10) -MaxChars 3;C 'overflow-rejected' $false}catch{C 'overflow-rejected' $true};$bad=$p|ConvertTo-Json -Depth 20|ConvertFrom-Json;$bad.value='tampered';try{Test-ESLettaProjectionReplay -Projection $bad;C 'projection-tamper-rejected' $false}catch{C 'projection-tamper-rejected' $true};$failed=@($cases|? status -eq 'failed');[pscustomobject]@{schemaVersion=1;validator='Test-ESLettaAdapter';status=$(if($failed.Count){'failed'}else{'passed'});caseCount=$cases.Count;passedCount=@($cases|? status -eq 'passed').Count;failedCount=$failed.Count;cases=@($cases);runtimeStatus='runtime-not-run';claimsNotProven=@('External Letta runtime equivalence','Unity/host runtime')}|ConvertTo-Json -Depth 10;if($failed.Count){exit 1}
